-- Four demonstration customers, each parked at a different point in the asset lifecycle.
--
-- The original seed (files 17 to 32) exists to give the DAO tests something to assert against, so
-- it is deliberately sparse and every row is load-bearing for some test. This file is the other
-- thing: enough joined-up data that every screen in the portal has something real to show, and a
-- reviewer can follow one customer from "ordered" through to "decommissioned" without typing
-- anything in.
--
-- Nothing here is referenced by a test. Change it freely.
--
--   1010  Northwind Coffee Roasters   WEST       live and healthy - order completed, asset active
--   1011  Beacon Hill Physio          NORTHEAST  order in flight - despatch window held, not yet built
--   1012  Lakeshore Legal Partners    CENTRAL    steady state with change requests against it
--   1013  Sundial Grocery Co-op       WEST       end of life - decommission, RMA, replacement
--
-- Id ranges are 1010-1013 / 2101+ / 3101+ / 4101+ / 5101+ / 6101+ / 7101+ / 8101+ / 9101+, which
-- sit above the original seed and below 100000 where the sequences start. Nothing generated by the
-- running application can collide with these.
--
-- Re-runnable: everything in those ranges is removed first, in reverse foreign-key order, and any
-- calendar place the demo orders hold is given back through the same procedure the application
-- uses so the reserved counts stay truthful.

-- ---------------------------------------------------------------------------
-- Clear down
-- ---------------------------------------------------------------------------
-- Release calendar places first. Deleting the reservation rows directly would leave
-- AMS_TIMESLOTS.RESERVED_COUNT overstated and slowly close down the calendar for everyone.
DECLARE
  l_status VARCHAR2(30);
BEGIN
  FOR r IN (SELECT TIMESLOT_ID, ENTITY_ID, ENTITY_TYPE_CD
              FROM AMS_TIMESLOT_RESERVATIONS
             WHERE RESERVATION_STATUS_CD = 'HELD'
               AND ((ENTITY_TYPE_CD IN ('SHIP', 'INSTALL') AND ENTITY_ID BETWEEN 6101 AND 6199)
                 OR (ENTITY_TYPE_CD = 'NCR' AND ENTITY_ID BETWEEN 8401 AND 8499))) LOOP
    AMS_SCHEDULING_PG.cancel_timeslot(r.TIMESLOT_ID, r.ENTITY_ID, r.ENTITY_TYPE_CD,
                                      'SEED', l_status);
  END LOOP;
END;
/
DELETE FROM AMS_TIMESLOT_RESERVATIONS
 WHERE (ENTITY_TYPE_CD IN ('SHIP', 'INSTALL') AND ENTITY_ID BETWEEN 6101 AND 6199)
    OR (ENTITY_TYPE_CD = 'NCR' AND ENTITY_ID BETWEEN 8401 AND 8499);
DELETE FROM AMS_EMAIL_QUEUE      WHERE EMAIL_ID        BETWEEN 9101 AND 9199;
DELETE FROM AMS_EVENTS           WHERE EVENT_ID        BETWEEN 8901 AND 8999;
DELETE FROM AMS_PORT_CONFIGS     WHERE PORT_ID         BETWEEN 8801 AND 8899;
DELETE FROM AMS_ASSET_RETURNS    WHERE ASSET_RETURN_ID BETWEEN 8701 AND 8799;
DELETE FROM AMS_MAINTENANCE_WINDOWS WHERE MAINT_WINDOW_ID BETWEEN 8601 AND 8699;
DELETE FROM AMS_SUBSCRIBER_PCS   WHERE SUBSCRIBER_PC_ID BETWEEN 8501 AND 8599;
DELETE FROM AMS_CIRCUIT_WINDOWS  WHERE NCR_ID          BETWEEN 8401 AND 8499;
DELETE FROM AMS_NCR_TYPES        WHERE NCR_ID          BETWEEN 8401 AND 8499;
DELETE FROM AMS_NETWORK_CHANGE_REQUESTS WHERE NCR_ID   BETWEEN 8401 AND 8499;
DELETE FROM AMS_RMAS             WHERE RMA_ID          BETWEEN 8301 AND 8399;
DELETE FROM AMS_DECOMMISSIONS    WHERE DECOMMISSION_ID BETWEEN 8201 AND 8299;
DELETE FROM AMS_INSTALLATIONS    WHERE INSTALLATION_ID BETWEEN 8101 AND 8199;
DELETE FROM AMS_ASSET_CONFIGS    WHERE CONFIG_ID       BETWEEN 7101 AND 7199;
DELETE FROM AMS_ORDERS           WHERE ORDER_ID        BETWEEN 6101 AND 6199;
DELETE FROM AMS_ASSETS           WHERE ASSET_ID        BETWEEN 5101 AND 5199;
DELETE FROM AMS_SERVICES         WHERE SERVICE_ID      BETWEEN 3101 AND 3199;
DELETE FROM AMS_CONTACTS         WHERE CONTACT_ID      BETWEEN 2101 AND 2199;
DELETE FROM AMS_ADDRESSES        WHERE ADDRESS_ID      BETWEEN 4101 AND 4199;
-- Rows the running application writes against these customers, which therefore have no id in the
-- demo range. Recording a visit happens on every customer selection, so once anyone has browsed a
-- demo customer the delete above fails on CUSTVISIT_CUSTOMER_FK without these.
DELETE FROM AMS_CUSTOMER_VISITS         WHERE CUSTOMER_ID BETWEEN 1010 AND 1013;
DELETE FROM AMS_CUSTOMER_EARLY_ADOPTERS WHERE CUSTOMER_ID BETWEEN 1010 AND 1013;
DELETE FROM AMS_CUSTOMER_SCHEDULES      WHERE CUSTOMER_ID BETWEEN 1010 AND 1013;
DELETE FROM AMS_CUSTOMERS        WHERE CUSTOMER_ID     BETWEEN 1010 AND 1013;

