-- ---------------------------------------------------------------------------
-- Despatch windows for the two open orders
-- ---------------------------------------------------------------------------
-- Booked through AMS_SCHEDULING_PG.reserve_timeslot rather than by writing the ledger row and
-- bumping RESERVED_COUNT by hand. Two reasons: the counter and the ledger stay consistent with each
-- other by construction, and the seed exercises the same procedure the ordering flow calls, so a
-- signature or logic change breaks the container build instead of surfacing on someone's screen.
--
-- The region comes from the shipping ZIP through AMS_INSTALL_REGIONS, which is how the calendar
-- service resolves it. An unmapped ZIP yields no windows at all, so this raises rather than quietly
-- leaving SHIP_WINDOW_ID null and making the order look like it never picked one.
DECLARE
  l_region      VARCHAR2(80);
  l_timeslot_id NUMBER;
  l_start       TIMESTAMP;
  l_status      VARCHAR2(30);
  l_message     VARCHAR2(4000);
BEGIN
  FOR o IN (SELECT o.ORDER_ID, o.ORDER_NUMBER, a.ZIP_CODE
              FROM AMS_ORDERS o
              JOIN AMS_ADDRESSES a ON a.ADDRESS_ID = o.SHIP_ADDRESS_ID
             WHERE o.ORDER_ID IN (6102, 6104)
             ORDER BY o.ORDER_ID) LOOP

    BEGIN
      SELECT REGION_CD INTO l_region
        FROM AMS_INSTALL_REGIONS WHERE ZIP_CODE = o.ZIP_CODE;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20040,
          'Demo seed: ZIP ' || o.ZIP_CODE || ' on order ' || o.ORDER_NUMBER
          || ' is not mapped in AMS_INSTALL_REGIONS');
    END;

    BEGIN
      SELECT TIMESLOT_ID, START_TM INTO l_timeslot_id, l_start
        FROM (SELECT TIMESLOT_ID, START_TM
                FROM AMS_TIMESLOTS
               WHERE CALL_TYPE_CD   = 'SHIP'
                 AND REGION_CD      = l_region
                 AND AVAILABLE_FL   = 'Y'
                 AND RESERVED_COUNT < CAPACITY
                 AND START_TM       > SYSTIMESTAMP
               ORDER BY START_TM)
       WHERE ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20041,
          'Demo seed: no bookable despatch window in region ' || l_region
          || ' for order ' || o.ORDER_NUMBER);
    END;

    AMS_SCHEDULING_PG.reserve_timeslot(l_timeslot_id, o.ORDER_ID, 'SHIP', l_start,
                                       'SEED', l_status, l_message);

    IF l_status <> 'OK' THEN
      RAISE_APPLICATION_ERROR(-20042,
        'Demo seed: could not hold despatch window ' || l_timeslot_id
        || ' for order ' || o.ORDER_NUMBER || ': ' || l_status || ' ' || l_message);
    END IF;

    UPDATE AMS_ORDERS SET SHIP_WINDOW_ID = l_timeslot_id WHERE ORDER_ID = o.ORDER_ID;
  END LOOP;
END;
/
